===== supabase/migrations/20261002200000_auth_perfis.sql
-- Perfis dos usuários do Filme Certo.
-- Cada linha nasce junto com o usuário em auth.users, pelo trigger abaixo,
-- na mesma transação: se o perfil falhar, o cadastro inteiro falha.

create table public.perfis (
  id uuid primary key references auth.users (id) on delete cascade,
  nome text not null check (char_length(nome) between 2 and 50),
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);

comment on table public.perfis is 'Dados públicos do usuário; um por linha de auth.users.';

alter table public.perfis enable row level security;

create policy "perfis: dono lê o próprio"
  on public.perfis for select
  to authenticated
  using (id = (select auth.uid()));

create policy "perfis: dono atualiza o próprio"
  on public.perfis for update
  to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

-- Sem políticas de insert e delete: só o trigger cria perfis e a exclusão
-- acontece em cascata quando o usuário é apagado.

create function public.criar_perfil()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.perfis (id, nome)
  values (new.id, btrim(coalesce(new.raw_user_meta_data ->> 'nome', '')));
  return new;
end;
$$;

revoke execute on function public.criar_perfil() from public, anon, authenticated;

create trigger ao_criar_usuario
  after insert on auth.users
  for each row execute function public.criar_perfil();

create function public.tocar_atualizado_em()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.atualizado_em = now();
  return new;
end;
$$;

create trigger perfis_atualizado_em
  before update on public.perfis
  for each row execute function public.tocar_atualizado_em();
===== supabase/migrations/20261005120000_preferencias.sql
-- Preferências do onboarding. Ter uma linha aqui significa onboarding concluído.

create type public.duracao_preferida as enum ('curta', 'media', 'longa', 'indiferente');
create type public.frequencia_assistir as enum ('raramente', 'mensal', 'semanal', 'diaria');

create table public.preferencias (
  usuario_id uuid primary key references auth.users (id) on delete cascade,
  generos int[] not null
    check (cardinality(generos) between 1 and 5)
    -- Os 19 gêneros de filme do TMDB (src/features/preferencias/generos.ts).
    check (generos <@ array[
      28, 16, 12, 10770, 35, 80, 99, 18, 10751, 14, 37, 878, 10752, 36, 9648, 10402, 10749, 27, 53
    ]),
  duracao public.duracao_preferida not null,
  frequencia public.frequencia_assistir not null,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);

comment on table public.preferencias is 'Gostos informados no onboarding; uma linha por usuário.';

alter table public.preferencias enable row level security;

create policy "preferencias: dono lê as próprias"
  on public.preferencias for select
  to authenticated
  using (usuario_id = (select auth.uid()));

create policy "preferencias: dono cria as próprias"
  on public.preferencias for insert
  to authenticated
  with check (usuario_id = (select auth.uid()));

create policy "preferencias: dono atualiza as próprias"
  on public.preferencias for update
  to authenticated
  using (usuario_id = (select auth.uid()))
  with check (usuario_id = (select auth.uid()));

create trigger preferencias_atualizado_em
  before update on public.preferencias
  for each row execute function public.tocar_atualizado_em();
