        .map((i) => ({ tmdb_id: i.tmdbId, titulo: i.titulo, ano: i.ano, minha_reacao: i.reacao, link: linkFilme(ctx.origem, i.tmdbId) }));
    const listas = lista ? [lista] : STATUS_LISTA;
    return ok(Object.fromEntries(listas.map((s) => [s, daLista(s)])));
  },
};
