export function erroDeEscrita(r: Extract<ResultadoDefinir<unknown>, { ok: false }>): ResultadoTool {
  if (r.erro === "filme-nao-encontrado") return erro(MSG.naoEncontrado);
  return erro(r.erro === "tmdb" ? MSG.tmdb : MSG.banco);
}

